import importlib
import os

mods = [
    "pypdf", "PyPDF2", "pdfplumber", "reportlab", "fitz", "pypdfium2",
    "pdf2image", "PIL",
]
for m in mods:
    try:
        importlib.import_module(m)
        print(f"OK   {m}")
    except Exception as e:
        print(f"MISS {m} ({type(e).__name__})")

print("\nWorking directory contents:")
for name in sorted(os.listdir(".")):
    size = os.path.getsize(name) if os.path.isfile(name) else "<dir>"
    print(f"  {name} ({size})")

import importlib.metadata as md
import os
import sys

print("Python:", sys.version)
print("Executable:", sys.executable)
print("\nInstalled distributions:")
try:
    dists = sorted((d.metadata.get("Name", "?") for d in md.distributions()))
    for d in dists:
        print("  ", d)
except Exception as e:
    print("  error:", e)

print("\nsite-packages candidates:")
for p in sys.path:
    if "site-packages" in p or "dist-packages" in p:
        print("  ", p)
        try:
            for name in sorted(os.listdir(p))[:50]:
                print("      ", name)
        except Exception:
            pass

print("\nreport.pdf raw dump:")
with open("report.pdf", "rb") as f:
    data = f.read()
print(f"size: {len(data)} bytes")
print(data[:2000].decode("latin-1", errors="replace"))

